def N(label,value,unit,why,tol=None,**kw):
 r=dict(label=label,type='numeric',answer=float(value),unit=unit,tolerance=max(abs(value)*.008,1e-100) if tol is None else tol,explanation=why);r.update(kw);return r
def C(label,answer,b,d,why):return dict(label=label,type='choice',answer=answer,options=[answer,b,d],explanation=why)
def R(n,parts,why,kind='problems',refs=None,assumptions=None,scope=None,notice=None):
 pages=([28] if n<=2 else [29]) if kind=='questions' else ([29] if n<=3 else [30] if n<=19 else [30,31] if n==20 else [31] if n<=42 else [32] if n<=59 else [32,33] if n==60 else [33])
 r=dict(id=f'physics-chapter-39-{kind}-{n}',parts=parts,reasoning=why+' Verification: '+parts[0]['explanation'],sourcePages=sorted(set(pages+(refs or []))),assumptions=assumptions or ['Chapter nonrelativistic stationary-well model unless the question explicitly tests its validity; hydrogen energies use13.6eV and Bohr radius a=5.29177e-11m.'])
 if scope:r['scope']=scope
 if notice:r['reviewNotice']=notice
 rows.append(r)
def E1(L,m=me):return h*h/(8*m*L*L)/e
def lam(E):return h*c/(E*e)
def photons(levels):return sorted(set(round(a-b,10) for a in levels for b in levels if a>b))
def radial(x):return 4*x*x*exp(-2*x)/a
def tail(x):return exp(-2*x)*(1+2*x+2*x*x)
def sym(label,answer,b,d,why):return C(label,answer,b,d,why)
