# Auditable independent identities and legacy comparison (baseline is Git HEAD).
import re
baseline=json.loads(gzip.decompress(subprocess.check_output(['git','show','HEAD:site/questions/answer-library-physics.json.gz'],cwd=ROOT)))['questions']
def legacy_fields(g):return g.get('parts',[]) if g and g.get('type')=='parts' else [g] if g else []
def partcode(p):
 m=re.match(r'^(?:Part )?\(?([a-z])\)?(?:\s|$|[·:])',p.get('label',''),re.I);return m.group(1).lower() if m else ''
def scaleunit(s):
 return {'nm':('m',1e-9),'pm':('m',1e-12),'μm':('m',1e-6),'fm':('m',1e-15),'GeV':('eV',1e9),'keV':('eV',1e3),'μeV':('eV',1e-6),'J':('eV',1/e),'':('dimensionless',1),'degrees':('deg',1),'detections':('dimensionless',1),'frequencies':('dimensionless',1),'points':('dimensionless',1),'states':('dimensionless',1)}.get(s,(s,1))
comp=[]
source_by_id={q['id']:q for q in source}
for r in rows:
 for old in legacy_fields(baseline.get(r['id'],{}).get('grader',source_by_id[r['id']].get('grader'))):
  if old.get('type')!='numeric':continue
  new=[p for p in r['parts'] if p['type']=='numeric' and partcode(p)==partcode(old)]
  if len(new)!=1:continue
  new=new[0];ou,os=scaleunit(old.get('unit',''));nu,ns=scaleunit(new.get('unit',''));ov=float(old['answer'])*os;nv=new['answer']*ns
  comp.append(dict(id=r['id'],part=partcode(old),old=float(old['answer']),oldUnit=old.get('unit',''),derived=new['answer'],derivedUnit=new['unit'],relativeDifference=abs(nv-ov)/max(abs(nv),abs(ov),1e-300),compatibleUnits=ou==nu))
assert all(x['compatibleUnits'] and x['relativeDifference']<.025 for x in comp)
